  return guide(`<b>${topic[0].toUpperCase()+topic.slice(1)}</b> controla la presentación sin cambiar el significado del HTML. Mantén la regla acotada, legible y adaptable al contenido.`,[['style','estilo'],['layout','distribución']],`¿Qué controla CSS al practicar ${topic}?`,['La presentación visual','La base de datos','El significado semántico'],0);
