 if(/función|parámetro|callback|funcional|closure|recursividad|algoritmo/.test(t))return guide('Una función recibe datos, realiza una tarea concreta y puede devolver un resultado. Las funciones pequeñas y con nombres claros son más fáciles de probar y reutilizar.',[['function','función'],['return value','valor devuelto']],'¿Qué debería hacer una función bien enfocada?',['Una tarea clara','Todas las tareas del programa','Ocultar sus entradas'],0);
 if(/array|filtro|iterador|map y set|estructura/.test(t))return guide('Las colecciones agrupan valores. Métodos como <code>filter</code>, <code>map</code> y <code>forEach</code> expresan transformaciones sin repetir lógica innecesaria.',[['array','arreglo'],['filter','filtrar']],'¿Qué devuelve filter?',['Elementos que cumplen una condición','Siempre un solo número','El HTML completo'],0);
