 try{setCloudLabel('Sincronizando…');await syncMissionProofs();const stamp=await cloud.saveProgress(state);state.cloudUpdatedAt=stamp;localStorage.setItem(key,JSON.stringify(state));setCloudLabel('✓ Progreso sincronizado','ok')}
