const updateStats=()=>{document.querySelector('#xp').textContent=state.xp;document.querySelector('#coins').textContent=state.coins;document.querySelector('#streak').textContent=state.streak};
const setActive=id=>{document.querySelectorAll('.bottom button').forEach(x=>x.classList.remove('active'));if(id)document.querySelector(id)?.classList.add('active')};
const validProgress=value=>value&&Array.isArray(value.done)&&Number.isFinite(value.xp);
function useCloudProgress(row){
 if(!validProgress(row?.progress))throw new Error('La copia de la nube no es válida');
 state=row.progress;state.cloudUpdatedAt=row.client_updated_at;state.localUpdatedAt=row.client_updated_at;
 localStorage.setItem(key,JSON.stringify(state));location.reload();
}
async function resolveSignedIn(){
 const remote=await cloud.loadProgress();
 if(!remote){pendingCloud=null;await syncProgress(false);return}
 const lastSync=state.cloudUpdatedAt?Date.parse(state.cloudUpdatedAt):0,localTime=state.localUpdatedAt?Date.parse(state.localUpdatedAt):0,remoteTime=Date.parse(remote.client_updated_at);
 const hasLegacyProgress=!state.cloudUpdatedAt&&(state.done.length>0||state.xp>0||state.coins>0||state.pets?.length>0);
 if(hasLegacyProgress||(remoteTime>lastSync&&localTime>lastSync)){pendingCloud=remote;accountView();return}
 if(remoteTime>lastSync){useCloudProgress(remote);return}
 pendingCloud=null;if(localTime>remoteTime)await syncProgress(false);
}
