function lesson(i){
 const l=lessons[i],answer=state.answers[i]||'',reward=l.boss?250:l.difficulty==='Desafío'?150:100;
 app.innerHTML=`<div class="lesson-head"><button class="back" aria-label="Volver al mapa">←</button><div><div class="kicker">${l.tier} · ${l.world} · MISIÓN ${i+1}</div><h1>${l.icon} ${l.title}</h1><div class="mission-meta"><span>${l.difficulty}</span><span>⚡ ${reward} XP</span>${l.boss?'<span>★ Proyecto</span>':''}</div></div></div><div class="lesson-layout"><article class="card"><h2>1. Aprende</h2><p>${l.learn}</p><p class="notice">El ejemplo enseña la herramienta; tu reto pide una solución diferente.</p><pre class="example"><code>${l.example.replaceAll('<','&lt;')}</code></pre><div class="fact"><b>💡 ¿Sabías que?</b><p>${l.fact}</p></div></article><aside class="card"><h2>English loot</h2>${l.terms.map(t=>`<div class="vocab"><b>${t[0]}</b><span>${t[1]}</span></div>`).join('')}</aside><section class="card challenge" data-lesson-index="${i}"><h2>2. Comprueba el concepto</h2><p><b>${l.quiz.q}</b></p><div class="quiz">${l.quiz.options.map((o,n)=>`<button data-answer="${n}">${o}</button>`).join('')}</div><div class="feedback" id="quizFeedback">Responde correctamente para desbloquear el editor.</div><div id="coding" class="coding locked-editor"><h2>3. ${l.boss?'Proyecto del mapa':'Tu misión'}</h2><p>${l.task}</p><textarea id="code" spellcheck="false" autocapitalize="off" autocomplete="off" placeholder="Primero supera la pregunta conceptual" disabled></textarea><label class="explain-box"><b>4. Explica tu solución</b><span>Describe con tus palabras qué hace tu código.</span><textarea id="explanation" maxlength="400" placeholder="Ejemplo: selecciono el elemento y después…" disabled>${escapeHtml(state.explanations[i]||'')}</textarea></label><div class="preview"><div class="preview-title">👁️ RESULTADO EN VIVO</div><iframe id="preview" sandbox="${l.type==='js'?'allow-scripts':''}" title="Resultado de tu código"></iframe></div><div class="actions"><button class="primary" id="check" disabled>Comprobar misión</button><button class="secondary" id="hint">Pedir una pista</button></div><div class="feedback" id="feedback" aria-live="polite"></div></div></section></div>`;
 const code=document.querySelector('#code'),explanation=document.querySelector('#explanation'),frame=document.querySelector('#preview'),feedback=document.querySelector('#feedback');code.value=answer;explanation.oninput=()=>{state.explanations[i]=explanation.value;localStorage.setItem(key,JSON.stringify(state))};
 const render=()=>{state.answers[i]=code.value;localStorage.setItem(key,JSON.stringify(state));frame.srcdoc=preview(code.value,l)};code.oninput=render;render();
 document.querySelectorAll('.quiz button').forEach(button=>button.onclick=()=>{
  const right=+button.dataset.answer===l.quiz.answer,qf=document.querySelector('#quizFeedback');
  document.querySelectorAll('.quiz button').forEach(x=>x.classList.remove('right','wrong'));button.classList.add(right?'right':'wrong');
  qf.className='feedback '+(right?'ok':'bad');qf.textContent=right?'¡Correcto! Editor desbloqueado.':'No es esa. Relee el fundamento y razona la respuesta.';
  if(right){document.querySelector('#coding').classList.remove('locked-editor');code.disabled=false;explanation.disabled=false;code.placeholder='Escribe tu propia solución...';document.querySelector('#check').disabled=false;code.focus()}
 });
 document.querySelector('.back').onclick=map;let hintStep=0;document.querySelector('#hint').onclick=()=>{hintStep++;feedback.className='feedback';feedback.textContent=hintStep===1?'Pista 1: identifica qué etiquetas, propiedades o instrucciones pide el reto.':hintStep===2?`Pista 2: ${l.hint}`:`Explicación: compara cada requisito con tu código, comprueba el resultado y cambia únicamente lo que falta.`};
 document.querySelector('#check').onclick=async()=>{const compact=v=>v.replace(/\s|;|"|'/g,'').toLowerCase(),copied=compact(code.value)===compact(l.example),tooShort=code.value.trim().length<12,understood=explanation.value.trim().split(/\s+/).length>=5,ok=!copied&&!tooShort&&understood&&l.check(code.value);feedback.className='feedback '+(ok?'ok':'bad');feedback.textContent=copied?'Copiar el ejemplo no completa la misión: úsalo solo como referencia.':tooShort?'La solución está demasiado corta. Revisa todos los requisitos.':!understood?'Explica tu solución con al menos cinco palabras para demostrar que la entendiste.':ok?'Comprobando la misión…':'Aún falta algún requisito. Relee la misión, prueba el resultado y vuelve a comprobar.';if(!ok){state.mistakes[i]=(state.mistakes[i]||0)+1;save();return}const proof={mission_index:i,language:l.type,code:code.value,explanation:explanation.value.trim()};const existing=state.pendingProofs.findIndex(item=>item.mission_index===i);if(existing>=0)state.pendingProofs[existing]=proof;else state.pendingProofs.push(proof);if(cloud.readSession()&&navigator.onLine){try{await cloud.completeMission(i,l.type,code.value,explanation.value.trim());state.pendingProofs=state.pendingProofs.filter(item=>item.mission_index!==i)}catch(error){feedback.className='feedback bad';feedback.textContent='La comprobación segura indicó: '+error.message;save();return}}feedback.className='feedback ok';feedback.textContent=`¡Misión superada! Ganaste ${reward} XP y ${Math.round(reward/10)} monedas 🪙${cloud.readSession()&&navigator.onLine?' · Verificada en la nube':' · Se verificará al conectarte'}`;if(!state.done.includes(i)){state.done.push(i);state.done.sort((a,b)=>a-b);state.xp+=reward;state.coins+=Math.round(reward/10);const ends=[35,75,105,130],mapIndex=ends.indexOf(i);if(mapIndex>=0&&!state.claimedMaps.includes(mapIndex)){state.claimedMaps.push(mapIndex);state.coins+=[100,150,225,350][mapIndex];feedback.textContent+=` · ¡Cofre del mapa: +${[100,150,225,350][mapIndex]} monedas!`}const dailyProgress=state.done.length-state.daily.start,dailyReward={1:15,3:50,5:90}[state.dailyGoal];if(dailyProgress>=state.dailyGoal&&!state.daily.claimed){state.daily.claimed=true;state.coins+=dailyReward;feedback.textContent+=` · ¡Meta diaria: +${dailyReward} monedas!`}const weeklyProgress=state.done.length-state.weekly.start;if(weeklyProgress>=10&&!state.weekly.claimed){state.weekly.claimed=true;state.coins+=180;feedback.textContent+=' · ¡Reto semanal: +180 monedas!'}recordActivity();playSuccess()}save();setTimeout(dashboard,1500)};
 window.scrollTo({top:0,behavior:'smooth'});
}
